window.ACTIVIDAD = {"id": "ut2-00-experiencia-usuario", "titulo": "¿Qué es la experiencia de usuario?", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Comprobar que entiendes qué es la experiencia de usuario (UX), qué factores la determinan y en qué se diferencia de la interfaz (UI) y de la usabilidad.", "minutos": 15, "preguntasPorIntento": 10, "aprobado": 50, "garantizar": ["arrastrar", "emparejar"], "diapositivas": {"11": "Diagrama UX y UI: a la izquierda, tareas UX (investigación con usuarios, arquitectura de información, wireframes, test A/B); a la derecha, tareas UI (diseño de interacción, diseño visual, tipografías, sistemas de diseño).", "12": "Experiencia de usuario: experiencia que tiene una persona al interactuar con todos los aspectos del producto de una empresa. Antes, durante y después.", "13": "Diseñadores de UX: se centran en el estudio del usuario, especialmente en su percepción y las sensaciones que le genera el producto a través de las interacciones que realiza.", "14": "UX, factores determinantes: 01 cómo ha descubierto la empresa y cómo ha llegado hasta ella; 02 el camino de interacciones en la interfaz para conseguir su propósito; 03 pensamientos y sentimientos que le surgen en el proceso.", "15": "¿Qué es una buena experiencia de usuario? La que garantiza que el producto o servicio web satisface las necesidades del usuario con una experiencia positiva. Puede ser para informarse, comprar, reservar, contactar con otros, etc.", "16": "La diseñadora UX no trabaja sola: colabora con investigadores de UX, departamento comercial, diseñadores UI y marketing para comprender el negocio, la empresa y a los usuarios.", "17": "Actividades de un diseñador UX: investigaciones (test con usuarios, card sorting, tree test, five second test, personas, focus group), evaluaciones (análisis heurísticos), análisis de datos (test A/B), arquitectura de información y wireframes.", "18": "El propósito del diseñador UX: poner el foco en el usuario para definir qué interfaz, qué contenidos y qué interacciones, para que perciba el producto como útil, usable y deseable.", "19": "Conceptos clave de UX: centrado en el usuario; para qué está en la web y qué espera; motivaciones y necesidades; selección de contenidos, estructuras e interacciones; análisis previo y posterior.", "20": "Investigación: «Preguntar es mejor que suponer».", "49": "Primero, UX se enfoca en conocer al usuario y proponer una experiencia que satisfaga sus necesidades. Segundo, UI da forma al producto digital que permite dicha experiencia. Principalmente visual.", "73": "Diagrama de Venn: la interfaz (UI) es lo que sucede en la pantalla, el artefacto; la experiencia (UX) es lo que sucede delante de la pantalla, el usuario; la interacción (IxD) está en la intersección.", "74": "Diagrama: un círculo grande UX contiene un círculo pequeño UI.", "119": "No confundir: la experiencia de usuario es la percepción positiva o negativa que genera la interacción; la usabilidad es la facilidad de uso para alcanzar un objetivo concreto. La usabilidad influye en la experiencia de usuario."}, "banco": [{"id": "q01", "tipo": "unica", "enunciado": "¿Qué es la experiencia de usuario (UX)?", "opciones": [{"id": "a", "texto": "La experiencia que tiene una persona al interactuar con todos los aspectos del producto de una empresa: antes, durante y después.", "correcta": true}, {"id": "b", "texto": "El aspecto visual de una web: colores, tipografías y botones."}, {"id": "c", "texto": "La facilidad con la que se usa una herramienta para conseguir un objetivo concreto."}, {"id": "d", "texto": "La programación de la parte de la web que muestra el navegador."}], "explicacion": "La UX abarca toda la relación de la persona con el producto de una empresa, antes, durante y después de usarlo. El aspecto visual es la UI, la facilidad de uso es la usabilidad y programar lo que muestra el navegador es trabajo de frontend.", "diapositiva": 12}, {"id": "q02", "tipo": "clasificar", "enunciado": "Irene compra unas zapatillas en una tienda online. Todo forma parte de su experiencia de usuario. Clasifica cada momento.", "categorias": [{"id": "c1", "texto": "Antes"}, {"id": "c2", "texto": "Durante"}, {"id": "c3", "texto": "Después"}], "elementos": [{"id": "e1", "texto": "Ve un anuncio de la tienda en Instagram.", "categoria": "c1"}, {"id": "e2", "texto": "Busca la tienda en Google.", "categoria": "c1"}, {"id": "e3", "texto": "Recorre el catálogo y añade las zapatillas al carrito.", "categoria": "c2"}, {"id": "e4", "texto": "Rellena el formulario de pago.", "categoria": "c2"}, {"id": "e5", "texto": "Recibe el email de confirmación del pedido.", "categoria": "c3"}, {"id": "e6", "texto": "Gestiona la devolución porque no son de su talla.", "categoria": "c3"}], "explicacion": "La UX no se limita al rato que pasamos en la web: empieza cuando descubrimos la empresa (antes), sigue con las interacciones en la interfaz (durante) y continúa con lo que ocurre al terminar: confirmaciones, envíos, devoluciones (después).", "diapositiva": 12}, {"id": "q03", "tipo": "multiple", "enunciado": "¿Cuáles son los factores determinantes de la experiencia de usuario?", "opciones": [{"id": "a", "texto": "Cómo ha descubierto la empresa o el producto y cómo ha llegado hasta él.", "correcta": true}, {"id": "b", "texto": "El camino de interacciones que realiza en la interfaz para conseguir su propósito.", "correcta": true}, {"id": "c", "texto": "Los pensamientos y sentimientos que le surgen en el proceso.", "correcta": true}, {"id": "d", "texto": "El lenguaje de programación con el que está hecha la web."}, {"id": "e", "texto": "El número de páginas que tiene la web."}], "explicacion": "Los tres factores determinantes de la UX son: cómo llega la persona hasta la empresa, el camino de interacciones que recorre y lo que piensa y siente mientras tanto. La tecnología o el tamaño de la web no la definen por sí mismos.", "diapositiva": 14}, {"id": "q04", "tipo": "vf", "grupo": "despues", "enunciado": "La experiencia de usuario termina en el momento en que la persona cierra la web.", "correcta": false, "explicacion": "Falso. La UX incluye el antes, el durante y el después: lo que pasa tras cerrar la web (el envío, la atención al cliente, una devolución) también forma parte de la experiencia.", "diapositiva": 12}, {"id": "q05", "tipo": "unica", "enunciado": "Una BUENA experiencia de usuario es la que…", "opciones": [{"id": "a", "texto": "garantiza que el producto satisface las necesidades del usuario con una experiencia positiva.", "correcta": true}, {"id": "b", "texto": "tiene muchas animaciones y efectos llamativos."}, {"id": "c", "texto": "muestra la mayor cantidad posible de información en la portada."}, {"id": "d", "texto": "refleja los gustos personales de quien la diseña."}], "explicacion": "Una buena UX garantiza que el producto satisface las necesidades del usuario (informarse, comprar, reservar, contactar…) y que la experiencia es positiva. Los efectos o la cantidad de información no lo aseguran.", "diapositiva": 15}, {"id": "q06", "tipo": "unica", "enunciado": "¿En qué se centran principalmente las personas que diseñan UX?", "opciones": [{"id": "a", "texto": "En estudiar al usuario: su percepción y las sensaciones que le genera el producto a través de sus interacciones.", "correcta": true}, {"id": "b", "texto": "En elegir la paleta de colores y las tipografías."}, {"id": "c", "texto": "En programar la base de datos y el servidor."}, {"id": "d", "texto": "En redactar los textos legales de la web."}], "explicacion": "El trabajo UX se centra en el usuario: cómo percibe el producto y qué siente al interactuar con él. Los colores y tipografías son tareas UI y la base de datos es trabajo de backend.", "diapositiva": 13}, {"id": "q07", "tipo": "vf", "enunciado": "La diseñadora UX trabaja sola, sin colaborar con otros departamentos, para no condicionar sus decisiones.", "correcta": false, "explicacion": "Falso. La diseñadora UX no trabaja sola: colabora con investigación UX, el departamento comercial, marketing y diseño UI para comprender el negocio, la empresa y a los usuarios.", "diapositiva": 16}, {"id": "q08", "tipo": "multiple", "enunciado": "¿Cuáles de estas actividades realiza habitualmente un diseñador o diseñadora UX?", "opciones": [{"id": "a", "texto": "Test con usuarios y card sorting.", "correcta": true}, {"id": "b", "texto": "Análisis heurísticos.", "correcta": true}, {"id": "c", "texto": "Test A/B.", "correcta": true}, {"id": "d", "texto": "Wireframes.", "correcta": true}, {"id": "e", "texto": "Programar la lógica del servidor."}, {"id": "f", "texto": "Administrar la base de datos."}], "explicacion": "Investigaciones (test con usuarios, card sorting…), evaluaciones (análisis heurísticos), análisis de datos (test A/B), arquitectura de información y wireframes son actividades UX. El servidor y la base de datos son tareas de backend.", "diapositiva": 17}, {"id": "q09", "tipo": "multiple", "enunciado": "El objetivo de la UX es que el usuario perciba el producto como…", "opciones": [{"id": "a", "texto": "Útil", "correcta": true}, {"id": "b", "texto": "Usable", "correcta": true}, {"id": "c", "texto": "Deseable", "correcta": true}, {"id": "d", "texto": "Complejo"}, {"id": "e", "texto": "Original a toda costa, aunque cueste usarlo"}], "explicacion": "La UX busca que el producto se perciba como útil, usable y deseable. La complejidad o la originalidad que dificulta el uso van en contra de una buena experiencia.", "diapositiva": 18}, {"id": "q10", "tipo": "unica", "enunciado": "Para definir la experiencia que satisfaga al usuario, ¿qué decide la persona que diseña UX?", "opciones": [{"id": "a", "texto": "Qué interfaz, qué contenidos y qué interacciones.", "correcta": true}, {"id": "b", "texto": "Qué servidor y qué base de datos se usarán."}, {"id": "c", "texto": "Solo los colores y las tipografías."}, {"id": "d", "texto": "El precio de los productos."}], "explicacion": "Poniendo el foco en las motivaciones y necesidades del usuario, la UX define qué interfaz, qué contenidos y qué interacciones tendrá el producto.", "diapositiva": 18}, {"id": "q11", "tipo": "vf", "enunciado": "En UX lo correcto es suponer lo que quiere el usuario, sin necesidad de preguntarle.", "correcta": false, "explicacion": "Falso. «Preguntar es mejor que suponer»: la UX se basa en investigar al usuario (entrevistas, encuestas, test…) y en analizar antes y después.", "diapositiva": 20}, {"id": "q12", "tipo": "multiple", "enunciado": "¿Cuáles son conceptos clave de la UX?", "opciones": [{"id": "a", "texto": "Estar centrada en el usuario.", "correcta": true}, {"id": "b", "texto": "Conocer para qué está el usuario en la web y qué espera.", "correcta": true}, {"id": "c", "texto": "Atender sus motivaciones y necesidades.", "correcta": true}, {"id": "d", "texto": "Hacer análisis previos y posteriores.", "correcta": true}, {"id": "e", "texto": "Centrarse solo en los gustos del cliente que paga el proyecto."}, {"id": "f", "texto": "Analizar únicamente cuando la web ya está publicada."}], "explicacion": "La UX está centrada en el usuario: para qué viene, qué espera, qué le motiva y qué necesita. Se analiza antes y después, no solo al final ni solo según el gusto del cliente.", "diapositiva": 19}, {"id": "q13", "tipo": "unica", "grupo": "ux-ui", "enunciado": "¿Qué frase describe mejor la relación entre UX y UI?", "opciones": [{"id": "a", "texto": "La UX conoce al usuario y propone la experiencia; la UI da forma al producto digital que la hace posible.", "correcta": true}, {"id": "b", "texto": "Son sinónimos: dos nombres para lo mismo."}, {"id": "c", "texto": "Primero se diseña la UI y después la UX decide si sirve."}, {"id": "d", "texto": "La UX solo se ocupa de lo visual y la UI de los usuarios."}], "explicacion": "Primero la UX se enfoca en conocer al usuario y proponer una experiencia que satisfaga sus necesidades; después la UI da forma, principalmente visual, al producto que permite esa experiencia.", "diapositiva": 49}, {"id": "q14", "tipo": "vf", "grupo": "ux-ui", "enunciado": "La interfaz de usuario (UI) es una parte de la experiencia de usuario (UX).", "correcta": true, "explicacion": "Verdadero. La UI está contenida en la UX: la interfaz es solo una de las partes con las que se construye la experiencia.", "diapositiva": 74}, {"id": "q15", "tipo": "clasificar", "enunciado": "Clasifica cada tarea según sea más propia de UX o de UI.", "categorias": [{"id": "c1", "texto": "UX"}, {"id": "c2", "texto": "UI"}], "elementos": [{"id": "e1", "texto": "Entrevistar a usuarios.", "categoria": "c1"}, {"id": "e2", "texto": "Organizar la arquitectura de información.", "categoria": "c1"}, {"id": "e3", "texto": "Hacer un test A/B.", "categoria": "c1"}, {"id": "e4", "texto": "Definir las tipografías.", "categoria": "c2"}, {"id": "e5", "texto": "Crear el sistema de diseño.", "categoria": "c2"}, {"id": "e6", "texto": "Diseñar el aspecto visual y gráfico.", "categoria": "c2"}], "explicacion": "Investigar a los usuarios, la arquitectura de información, los wireframes y los test A/B son tareas UX. El diseño visual, las tipografías, el diseño de interacción y el sistema de diseño son tareas UI.", "diapositiva": 11}, {"id": "q16", "tipo": "unica", "enunciado": "En el diagrama «artefacto – usuario», ¿qué representa la experiencia (UX)?", "opciones": [{"id": "a", "texto": "Lo que sucede delante de la pantalla: en el usuario.", "correcta": true}, {"id": "b", "texto": "Lo que sucede en la pantalla: en el artefacto."}, {"id": "c", "texto": "La intersección entre interfaz y usuario."}, {"id": "d", "texto": "El código que se ejecuta en el servidor."}], "explicacion": "La interfaz (UI) es lo que sucede en la pantalla; la experiencia (UX) es lo que sucede delante de ella, en el usuario. La intersección entre ambas es la interacción (IxD).", "diapositiva": 73}, {"id": "q17", "tipo": "vf", "grupo": "usabilidad", "enunciado": "Experiencia de usuario y usabilidad son exactamente lo mismo.", "correcta": false, "explicacion": "Falso. La usabilidad es la facilidad de uso para alcanzar un objetivo concreto; la UX es la percepción positiva o negativa que genera toda la interacción. La usabilidad influye en la UX, pero no son lo mismo.", "diapositiva": 119}, {"id": "q18", "tipo": "unica", "grupo": "usabilidad", "enunciado": "¿Qué relación hay entre la usabilidad y la experiencia de usuario?", "opciones": [{"id": "a", "texto": "La usabilidad influye en la UX: si algo es fácil de usar, contribuye a una percepción positiva.", "correcta": true}, {"id": "b", "texto": "Ninguna: son disciplinas independientes."}, {"id": "c", "texto": "La UX es una parte de la usabilidad."}, {"id": "d", "texto": "Son sinónimos."}], "explicacion": "No hay que confundirlas: la usabilidad mide la facilidad de uso y la UX la percepción global. La usabilidad influye en la experiencia de usuario.", "diapositiva": 119}, {"id": "q19", "tipo": "unica", "grupo": "despues", "enunciado": "Marcos compra unos auriculares en una web. El pago va perfecto, pero el pedido llega dos semanas tarde y nadie contesta sus emails. ¿Ha tenido una buena experiencia de usuario?", "opciones": [{"id": "a", "texto": "No: la experiencia de usuario también incluye lo que ocurre después de usar la web.", "correcta": true}, {"id": "b", "texto": "Sí, porque la web funcionó bien."}, {"id": "c", "texto": "Sí, porque la UX solo depende de la interfaz."}, {"id": "d", "texto": "No se puede saber: la UX solo se mide con test A/B."}], "explicacion": "La UX abarca el antes, el durante y el después. Un buen proceso de compra no compensa un mal envío o una mala atención: los sentimientos de Marcos sobre la empresa serán negativos.", "diapositiva": 12}, {"id": "q20", "tipo": "unica", "enunciado": "Una web para comprar entradas de conciertos es preciosa, pero para comprar una entrada hay que rellenar cuatro formularios seguidos. Desde el punto de vista de la UX, ¿qué falla?", "opciones": [{"id": "a", "texto": "El camino de interacciones para conseguir su propósito es demasiado largo.", "correcta": true}, {"id": "b", "texto": "El diseño visual."}, {"id": "c", "texto": "Nada: si es bonita, la experiencia es buena."}, {"id": "d", "texto": "El servidor de la web."}], "explicacion": "El camino de interacciones que recorre el usuario para conseguir su propósito es un factor determinante de la UX. Una interfaz bonita no compensa un proceso largo y pesado.", "diapositiva": 14}, {"id": "q21", "tipo": "vf", "enunciado": "La experiencia de usuario tiene en cuenta los pensamientos y sentimientos que surgen en el usuario durante el proceso.", "correcta": true, "explicacion": "Verdadero. Los pensamientos y sentimientos del usuario durante el proceso son uno de los tres factores determinantes de la UX.", "diapositiva": 14}, {"id": "q22", "tipo": "unica", "enunciado": "Descubres un restaurante porque una amiga lo recomienda en redes sociales y luego entras en su web para reservar. ¿Esa recomendación forma parte de tu experiencia de usuario?", "opciones": [{"id": "a", "texto": "Sí: cómo descubres la empresa y llegas hasta ella es un factor determinante de la UX.", "correcta": true}, {"id": "b", "texto": "No: la UX empieza cuando entras en la web."}, {"id": "c", "texto": "No: las redes sociales solo son marketing."}, {"id": "d", "texto": "Solo si la recomendación incluye un enlace."}], "explicacion": "Cómo ha descubierto el usuario la empresa y cómo ha llegado hasta ella es el primer factor determinante de la UX: la experiencia empieza antes de entrar en la web.", "diapositiva": 14}, {"id": "q23", "tipo": "vf", "enunciado": "Una buena experiencia de usuario solo es importante en las tiendas online.", "correcta": false, "explicacion": "Falso. Una buena UX es importante sea cual sea el objetivo del usuario: informarse, comprar, reservar, contactar con otras personas, etc.", "diapositiva": 15}, {"id": "q24", "tipo": "unica", "enunciado": "¿Qué pregunta guía el trabajo de UX?", "opciones": [{"id": "a", "texto": "¿Para qué está el usuario en la web y qué espera encontrar?", "correcta": true}, {"id": "b", "texto": "¿Qué colores están de moda este año?"}, {"id": "c", "texto": "¿Qué tecnología es la más moderna?"}, {"id": "d", "texto": "¿Qué le gusta a quien dirige la empresa?"}], "explicacion": "La UX está centrada en el usuario: para qué está en la web, qué espera, cuáles son sus motivaciones y necesidades.", "diapositiva": 19}, {"id": "q25", "tipo": "arrastrar", "enunciado": "Completa el diagrama del contacto entre el usuario y el artefacto: coloca cada término en su zona.", "imagen": "img/diagrama-ui-ixd-ux.svg", "alt": "Diagrama de dos círculos que se solapan. Zona 1: la parte izquierda, rotulada «en la pantalla». Zona 2: la intersección de los dos círculos. Zona 3: la parte derecha, rotulada «delante de la pantalla».", "zonas": [{"id": "z1", "x": 23, "y": 45, "correcta": "t1"}, {"id": "z2", "x": 50, "y": 45, "correcta": "t2"}, {"id": "z3", "x": 77, "y": 45, "correcta": "t3"}], "terminos": [{"id": "t1", "texto": "Interfaz (UI)"}, {"id": "t2", "texto": "Interacción (IxD)"}, {"id": "t3", "texto": "Experiencia (UX)"}, {"id": "t4", "texto": "Usabilidad"}], "explicacion": "La interfaz (UI) es lo que sucede en la pantalla, en el artefacto. La experiencia (UX) es lo que sucede delante de la pantalla, en el usuario. Donde se encuentran está la interacción (IxD): cómo se opera la interfaz y cómo responde. La usabilidad no es una zona del diagrama: es una cualidad que influye en la UX.", "diapositiva": 73}, {"id": "q26", "tipo": "arrastrar", "grupo": "ux-ui", "enunciado": "Este diagrama representa la relación entre UX y UI. Coloca cada término en su círculo.", "imagen": "img/diagrama-ux-contiene-ui.svg", "alt": "Diagrama con un círculo grande (zona 1) que contiene en su interior un círculo pequeño (zona 2).", "zonas": [{"id": "z1", "x": 35, "y": 37, "correcta": "t1"}, {"id": "z2", "x": 62, "y": 62, "correcta": "t2"}], "terminos": [{"id": "t1", "texto": "UX"}, {"id": "t2", "texto": "UI"}, {"id": "t3", "texto": "Backend"}], "explicacion": "La UX es el círculo grande: abarca toda la experiencia. La UI es una parte de ella, el círculo pequeño de dentro. El backend no forma parte de este diagrama: es la parte lógica del servidor.", "diapositiva": 74}, {"id": "q27", "tipo": "emparejar", "enunciado": "Empareja cada concepto con su definición.", "pares": [{"id": "p1", "izquierda": "Experiencia de usuario (UX)", "derecha": "Lo que vive la persona al interactuar con todo el producto: antes, durante y después."}, {"id": "p2", "izquierda": "Interfaz de usuario (UI)", "derecha": "Todos los elementos del producto con los que el usuario interactúa."}, {"id": "p3", "izquierda": "Diseño de interacción (IxD)", "derecha": "Cómo se opera la interfaz y cómo responde a la persona."}, {"id": "p4", "izquierda": "Usabilidad", "derecha": "Facilidad de uso para conseguir un objetivo concreto."}], "distractores": ["El código que se ejecuta en el servidor."], "explicacion": "La UX es la experiencia completa (antes, durante y después); la UI, los elementos con los que se interactúa; la IxD, la forma de operar la interfaz y su respuesta; y la usabilidad, la facilidad de uso para lograr un objetivo. El código del servidor es trabajo de backend.", "diapositiva": 12}, {"id": "q28", "tipo": "emparejar", "enunciado": "Empareja cada factor determinante de la UX con un ejemplo.", "pares": [{"id": "p1", "izquierda": "Cómo descubre la empresa y llega hasta ella", "derecha": "Ve un anuncio en Instagram y entra en la web."}, {"id": "p2", "izquierda": "El camino de interacciones", "derecha": "Necesita seis pasos para completar el pago."}, {"id": "p3", "izquierda": "Pensamientos y sentimientos", "derecha": "Se agobia porque no encuentra el carrito."}], "distractores": ["La empresa elige su color corporativo."], "explicacion": "Los tres factores determinantes de la UX son cómo llega la persona a la empresa, el camino de interacciones que recorre y lo que piensa y siente en el proceso. Elegir el color corporativo es una decisión de marca, no un factor de la experiencia del usuario.", "diapositiva": 14}]};
